using System.Collections;
using System.Collections.Generic;
using UnityEngine;
#if UNITY_EDITOR
using UnityEditor;
#endif

public class LumberPrototypeBootstrap : MonoBehaviour
{
    Transform player,axePivot,carryAnchor,sawmill; Camera cam; Animator animator;
    bool wasMoving,wasRunning,chopping; float moveHeldTime,nextChopTime,nextDeliverTime; int boards,carriedLogs;
    TreeNode nearbyTree; GUIStyle hudStyle,hintStyle; readonly List<GameObject> backpackVisuals=new List<GameObject>();
    const float WalkSpeed=2.6f,RunSpeed=4.4f,RunDelay=1.35f,ChopRange=2.25f,TreeStopDistance=1.1f,SawmillRange=2.7f; const int MaxLogs=50;
    Vector2 touchStart; bool dragging;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void AutoStart(){if(FindFirstObjectByType<LumberPrototypeBootstrap>()==null)new GameObject("Lumber Empire Demo").AddComponent<LumberPrototypeBootstrap>();}
    void Start(){foreach(var c in FindObjectsByType<Camera>(FindObjectsSortMode.None))Destroy(c.gameObject);RenderSettings.ambientLight=new Color(.72f,.76f,.68f);MakeGround();MakeLight();MakeCamera();MakePlayer();MakeForestPlot();MakeSawmill();}
    Vector2 ReadMoveInput(){Vector2 input=new Vector2(Input.GetAxisRaw("Horizontal"),Input.GetAxisRaw("Vertical"));if(Input.touchCount>0){Touch t=Input.GetTouch(0);if(t.phase==TouchPhase.Began){touchStart=t.position;dragging=true;}if(dragging&&(t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary)){Vector2 delta=t.position-touchStart;if(delta.magnitude>12)input=Vector2.ClampMagnitude(delta/90f,1);}if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled)dragging=false;}else if(Input.GetMouseButtonDown(0)){touchStart=Input.mousePosition;dragging=true;}else if(Input.GetMouseButton(0)&&dragging){Vector2 delta=(Vector2)Input.mousePosition-touchStart;if(delta.magnitude>12)input=Vector2.ClampMagnitude(delta/90f,1);}else if(Input.GetMouseButtonUp(0))dragging=false;return input;}
    void Update(){if(player==null)return;nearbyTree=FindClosestTree();bool moving=false;if(!chopping){Vector2 input=ReadMoveInput();Vector3 d=new Vector3(input.x,0,input.y);if(d.sqrMagnitude>1)d.Normalize();moving=d.sqrMagnitude>.01f;moveHeldTime=moving?moveHeldTime+Time.deltaTime:0;bool running=moving&&moveHeldTime>=RunDelay;float speed=running?RunSpeed:WalkSpeed;if(moving){Vector3 next=player.position+d*speed*Time.deltaTime;if(FindTreeNear(next,TreeStopDistance)==null)player.position=next;player.rotation=Quaternion.Slerp(player.rotation,Quaternion.LookRotation(d),12*Time.deltaTime);}if(animator!=null){if(!moving&&wasMoving)FreezeStandingPose();else if(moving&&!wasMoving)StartWalking();else if(running&&!wasRunning)StartRunning();}wasMoving=moving;wasRunning=running;}
        if(!moving&&!chopping&&nearbyTree!=null&&carriedLogs<MaxLogs&&Time.time>=nextChopTime){nextChopTime=Time.time+.62f;StartCoroutine(ChopTree(nearbyTree));}
        if(carriedLogs>0&&NearSawmill()&&Time.time>=nextDeliverTime){nextDeliverTime=Time.time+1f;DeliverAllLogs();}
        if(cam!=null){Vector3 target=player.position+new Vector3(9.5f,11,-9.5f);cam.transform.position=Vector3.Lerp(cam.transform.position,target,5*Time.deltaTime);}}
    TreeNode FindClosestTree(){TreeNode best=null;float bestD=ChopRange*ChopRange;foreach(var t in FindObjectsByType<TreeNode>(FindObjectsSortMode.None)){if(t.felled)continue;Vector3 d=t.transform.position-player.position;d.y=0;if(d.sqrMagnitude<bestD){bestD=d.sqrMagnitude;best=t;}}return best;}
    TreeNode FindTreeNear(Vector3 p,float range){float rr=range*range;foreach(var t in FindObjectsByType<TreeNode>(FindObjectsSortMode.None)){if(t.felled)continue;Vector3 d=t.transform.position-p;d.y=0;if(d.sqrMagnitude<rr)return t;}return null;}
    IEnumerator ChopTree(TreeNode tree){if(tree==null||tree.felled||carriedLogs>=MaxLogs)yield break;chopping=true;wasMoving=false;wasRunning=false;moveHeldTime=0;Vector3 face=tree.transform.position-player.position;face.y=0;if(face.sqrMagnitude>.01f)player.rotation=Quaternion.LookRotation(face);if(animator!=null)FreezeStandingPose();yield return SwingAxe();tree.Hit();yield return ImpactFlash(tree.transform.position+Vector3.up*1.15f);if(tree.hitsLeft<=0){tree.felled=true;yield return FellTree(tree);}chopping=false;}
    IEnumerator SwingAxe(){if(axePivot==null)yield break;axePivot.gameObject.SetActive(true);yield return new WaitForSeconds(.44f);axePivot.gameObject.SetActive(false);}
    IEnumerator ImpactFlash(Vector3 p){for(int i=0;i<3;i++){var chip=GameObject.CreatePrimitive(PrimitiveType.Cube);chip.transform.position=p;chip.transform.localScale=new Vector3(.13f,.07f,.24f);Paint(chip,new Color(.82f,.54f,.25f));Destroy(chip.GetComponent<Collider>());Vector3 end=p+new Vector3(Random.Range(-.65f,.65f),Random.Range(.25f,.65f),Random.Range(-.65f,.65f));StartCoroutine(FlyChip(chip,p,end));}yield return new WaitForSeconds(.12f);}
    IEnumerator FlyChip(GameObject chip,Vector3 start,Vector3 end){float t=0;while(t<1&&chip!=null){t+=Time.deltaTime*4.5f;chip.transform.position=Vector3.Lerp(start,end,t)+Vector3.up*Mathf.Sin(t*Mathf.PI)*.25f;yield return null;}if(chip!=null)Destroy(chip);}
    IEnumerator FellTree(TreeNode tree){Transform tr=tree.transform;Quaternion start=tr.rotation;Vector3 away=tr.position-player.position;away.y=0;Vector3 axis=Vector3.Cross(Vector3.up,away.normalized);if(axis.sqrMagnitude<.01f)axis=Vector3.right;Quaternion end=Quaternion.AngleAxis(86,axis)*start;float t=0;while(t<1){t+=Time.deltaTime*1.55f;tr.rotation=Quaternion.Slerp(start,end,Mathf.SmoothStep(0,1,t));yield return null;}Vector3 p=tr.position;yield return new WaitForSeconds(.15f);Destroy(tr.gameObject);MakeStump(p);AddLogs(Mathf.Min(3,MaxLogs-carriedLogs));}
    void MakeStump(Vector3 p){var stump=GameObject.CreatePrimitive(PrimitiveType.Cylinder);stump.name="Tree Stump";stump.transform.position=p+Vector3.up*.2f;stump.transform.localScale=new Vector3(.48f,.2f,.48f);Paint(stump,new Color(.5f,.3f,.14f));Destroy(stump.GetComponent<Collider>());}
    void AddLogs(int amount){carriedLogs=Mathf.Min(MaxLogs,carriedLogs+amount);RefreshBackpack();}
    void RefreshBackpack(){if(carryAnchor==null){var a=new GameObject("Log Backpack");a.transform.SetParent(player,false);a.transform.localPosition=new Vector3(0,1.0f,-.42f);carryAnchor=a.transform;}foreach(var g in backpackVisuals)if(g!=null)Destroy(g);backpackVisuals.Clear();int visible=Mathf.Min(carriedLogs,12);for(int i=0;i<visible;i++){var log=GameObject.CreatePrimitive(PrimitiveType.Cylinder);log.name="Back Log";log.transform.SetParent(carryAnchor,false);int layer=i/4,slot=i%4;log.transform.localPosition=new Vector3((slot-1.5f)*.18f,layer*.20f,0);log.transform.localRotation=Quaternion.Euler(0,0,90);log.transform.localScale=new Vector3(.12f,.42f,.12f);Paint(log,new Color(.57f,.33f,.14f));Destroy(log.GetComponent<Collider>());backpackVisuals.Add(log);}}
    bool NearSawmill(){if(sawmill==null)return false;Vector3 d=sawmill.position-player.position;d.y=0;return d.sqrMagnitude<=SawmillRange*SawmillRange;}
    void DeliverAllLogs(){int delivered=carriedLogs;if(delivered<=0)return;carriedLogs=0;boards+=delivered*2;RefreshBackpack();StartCoroutine(BoardPop(Mathf.Min(delivered,6)));}
    IEnumerator BoardPop(int count){if(sawmill==null)yield break;for(int i=0;i<count;i++){var b=GameObject.CreatePrimitive(PrimitiveType.Cube);b.transform.position=sawmill.position+new Vector3(-1.1f+(i%3)*.75f,.75f+(i/3)*.16f,-.7f);b.transform.localScale=new Vector3(.65f,.12f,.22f);Paint(b,new Color(.78f,.53f,.26f));Destroy(b.GetComponent<Collider>());Destroy(b,2.2f);}yield return null;}
    void OnGUI(){if(hudStyle==null){hudStyle=new GUIStyle(GUI.skin.box){fontSize=23,alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold};hintStyle=new GUIStyle(GUI.skin.box){fontSize=18,alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold};}GUI.Box(new Rect(18,18,220,52),"LOGS "+carriedLogs+"/"+MaxLogs+"   BOARDS "+boards,hudStyle);string hint="";if(carriedLogs>=MaxLogs)hint="BACKPACK FULL • GO TO SAWMILL";else if(carriedLogs>0&&NearSawmill())hint="DELIVERING LOGS...";else if(nearbyTree!=null&&!nearbyTree.felled)hint="AUTO CHOPPING • "+nearbyTree.hitsLeft+" HITS";if(hint!="")GUI.Box(new Rect(Screen.width/2-190,Screen.height-82,380,52),hint,hintStyle);}
    void StartWalking(){animator.speed=1;animator.Play("Walking",0,0);animator.Update(0);}void StartRunning(){animator.speed=1;int h=Animator.StringToHash("Running");if(animator.HasState(0,h))animator.Play(h,0,0);else{animator.Play("Walking",0,0);animator.speed=1.55f;}animator.Update(0);}void FreezeStandingPose(){animator.speed=1;animator.Play("Walking",0,.08f);animator.Update(0);animator.speed=0;}
    void MakePlayer(){animator=FindFirstObjectByType<Animator>();GameObject obj=animator!=null?animator.gameObject:null;
#if UNITY_EDITOR
        if(obj==null){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Hodaart/HodaartLowPolyCharacterCollection3/Prefabs/Character 06.prefab");if(prefab!=null)obj=Instantiate(prefab);}
#endif
        if(obj==null){Debug.LogError("No playable character found in scene/build.");return;}var root=new GameObject("Lumberjack Player");obj.transform.SetParent(root.transform,true);obj.transform.position=Vector3.zero;obj.transform.rotation=Quaternion.identity;animator=obj.GetComponentInChildren<Animator>();if(animator!=null){animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();FreezeStandingPose();}GroundVisual(obj,.05f);player=root.transform;MakeAxe();}
    void MakeAxe(){var pivot=new GameObject("Axe Pivot");pivot.transform.SetParent(player);pivot.transform.localPosition=new Vector3(.48f,1.25f,.48f);axePivot=pivot.transform;var handle=GameObject.CreatePrimitive(PrimitiveType.Cylinder);handle.transform.SetParent(axePivot);handle.transform.localPosition=new Vector3(0,.42f,0);handle.transform.localScale=new Vector3(.055f,.48f,.055f);Paint(handle,new Color(.38f,.19f,.07f));Destroy(handle.GetComponent<Collider>());var head=GameObject.CreatePrimitive(PrimitiveType.Cube);head.transform.SetParent(axePivot);head.transform.localPosition=new Vector3(.12f,.88f,0);head.transform.localScale=new Vector3(.34f,.18f,.12f);Paint(head,new Color(.35f,.38f,.4f));Destroy(head.GetComponent<Collider>());pivot.SetActive(false);}
    void GroundVisual(GameObject visual,float y){if(animator!=null)animator.Update(0);float minY=float.PositiveInfinity;foreach(var r in visual.GetComponentsInChildren<Renderer>()){var skinned=r as SkinnedMeshRenderer;if(skinned!=null)skinned.updateWhenOffscreen=true;minY=Mathf.Min(minY,r.bounds.min.y);}if(float.IsFinite(minY))visual.transform.position+=Vector3.up*(y-minY);}
    Material Mat(Color c){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Sprites/Default");var m=new Material(s);m.color=c;return m;}void Paint(GameObject o,Color c){var r=o.GetComponent<Renderer>();if(r!=null)r.material=Mat(c);}
    void MakeGround(){var g=GameObject.CreatePrimitive(PrimitiveType.Plane);g.name="World Ground";g.transform.localScale=new Vector3(4.2f,1,4.2f);Paint(g,new Color(.34f,.59f,.25f));}
    void MakeLight(){var o=new GameObject("Warm Sun");var l=o.AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.25f;l.color=new Color(1,.91f,.76f);o.transform.rotation=Quaternion.Euler(48,-35,0);}
    void MakeCamera(){var o=new GameObject("Main Camera");o.tag="MainCamera";cam=o.AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=7.5f;o.transform.position=new Vector3(9.5f,11,-9.5f);o.transform.rotation=Quaternion.Euler(38,-42,0);cam.backgroundColor=new Color(.65f,.82f,.92f);}
    void MakeForestPlot(){var plot=GameObject.CreatePrimitive(PrimitiveType.Cube);plot.name="Forest Plot";plot.transform.position=new Vector3(-5.5f,.04f,1.5f);plot.transform.localScale=new Vector3(10,.08f,11);Paint(plot,new Color(.25f,.46f,.19f));Destroy(plot.GetComponent<Collider>());float startX=-9.2f,startZ=-2.3f;for(int row=0;row<4;row++)for(int col=0;col<4;col++)Tree(new Vector3(startX+col*2.45f,0,startZ+row*2.45f));}
    void Tree(Vector3 p){var r=new GameObject("Tree");r.transform.position=p;r.AddComponent<TreeNode>();var t=GameObject.CreatePrimitive(PrimitiveType.Cylinder);t.transform.SetParent(r.transform);t.transform.localPosition=new Vector3(0,1.4f,0);t.transform.localScale=new Vector3(.42f,1.4f,.42f);Paint(t,new Color(.42f,.23f,.1f));for(int i=0;i<3;i++){var f=GameObject.CreatePrimitive(PrimitiveType.Sphere);f.transform.SetParent(r.transform);f.transform.localPosition=new Vector3((i-1)*.5f,3.05f+(i%2)*.35f,0);f.transform.localScale=new Vector3(1.42f,1.22f,1.42f);Paint(f,new Color(.12f,.48f,.16f));}}
    void MakeSawmill(){var root=new GameObject("SAWMILL");root.transform.position=new Vector3(5.3f,0,1.5f);sawmill=root.transform;var pad=GameObject.CreatePrimitive(PrimitiveType.Cube);pad.transform.SetParent(root.transform);pad.transform.localPosition=new Vector3(0,.08f,0);pad.transform.localScale=new Vector3(5.2f,.16f,4.4f);Paint(pad,new Color(.52f,.42f,.28f));Destroy(pad.GetComponent<Collider>());var table=GameObject.CreatePrimitive(PrimitiveType.Cube);table.transform.SetParent(root.transform);table.transform.localPosition=new Vector3(0,.65f,0);table.transform.localScale=new Vector3(3.8f,.32f,1.45f);Paint(table,new Color(.38f,.23f,.12f));var blade=GameObject.CreatePrimitive(PrimitiveType.Cylinder);blade.transform.SetParent(root.transform);blade.transform.localPosition=new Vector3(0,1.38f,0);blade.transform.localScale=new Vector3(1.15f,.12f,1.15f);blade.transform.rotation=Quaternion.Euler(90,0,0);Paint(blade,new Color(.72f,.75f,.78f));var roof=GameObject.CreatePrimitive(PrimitiveType.Cube);roof.transform.SetParent(root.transform);roof.transform.localPosition=new Vector3(0,2.65f,0);roof.transform.localScale=new Vector3(4.8f,.22f,3.4f);Paint(roof,new Color(.52f,.17f,.1f));for(int side=-1;side<=1;side+=2)for(int z=-1;z<=1;z+=2){var post=GameObject.CreatePrimitive(PrimitiveType.Cube);post.transform.SetParent(root.transform);post.transform.localPosition=new Vector3(side*2f,1.45f,z*1.35f);post.transform.localScale=new Vector3(.18f,2.7f,.18f);Paint(post,new Color(.3f,.18f,.09f));}var sign=GameObject.CreatePrimitive(PrimitiveType.Cube);sign.transform.SetParent(root.transform);sign.transform.localPosition=new Vector3(0,2.15f,-1.58f);sign.transform.localScale=new Vector3(2.4f,.55f,.12f);Paint(sign,new Color(.82f,.58f,.25f));}
}
